72	function zodMessage(e: ZodError): string {
73	  const issue = e.issues[0]
74	  if (!issue) return 'Invalid input'
75	  const path = issue.path.map(String).join('.')
76	  return path ? `Invalid input: ${path}: ${issue.message}` : `Invalid input: ${issue.message}`
77	}
